using System;using System.IO;using System.Xml;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
sealed class ProjectInformation {public string Name="",Location="";public string NameLine{get{return "Project: "+(Name.Length==0?"(not set)":Name);}}public string LocationLine{get{return "Location: "+(Location.Length==0?"(not set)":Location);}}}
static class ProjectInfoStore {
 public static string DirectoryPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BeamTools");
 public static ProjectInformation Read(){string path=Path.Combine(DirectoryPath,"ProjectInformation.xml");if(!File.Exists(path))return new ProjectInformation();var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=10000}))d.Load(r);if(d.DocumentElement.Name!="ProjectInformation")throw new Exception("Invalid saved project information.");return new ProjectInformation{Name=d.DocumentElement.GetAttribute("name"),Location=d.DocumentElement.GetAttribute("location")};}
 public static void Save(string name,string location){name=name.Trim();location=location.Trim();if(name.Length>100||location.Length>100||name.Contains("\n")||location.Contains("\n")||name.Contains("\r")||location.Contains("\r"))throw new Exception("Use a single line, maximum100characters per field.");var d=new XmlDocument();var root=d.CreateElement("ProjectInformation");root.SetAttribute("name",name);root.SetAttribute("location",location);d.AppendChild(root);Directory.CreateDirectory(DirectoryPath);string path=Path.Combine(DirectoryPath,"ProjectInformation.xml"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{d.Save(temp);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
class ProjectInformationForm:Form {
 public ProjectInformationForm(){AppBrand.Apply(this);if(!AccessCodes.CanUseApp(8))throw new Exception("This app is not included in your current access.");Shown+=(s,e)=>InputFocus.Apply(this);Text="Project Information";ClientSize=new Size(650,330);MinimumSize=new Size(666,369);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(243,246,250);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=7};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,25));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,25));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,38));layout.Controls.Add(new Label{Text="PROJECT INFORMATION",Font=new Font("Segoe UI",16,FontStyle.Bold),AutoSize=true});layout.Controls.Add(new Label{Text="Project Name",AutoSize=true});var name=new TextBox{Dock=DockStyle.Fill,MaxLength=100};layout.Controls.Add(name);layout.Controls.Add(new Label{Text="Project Location",AutoSize=true});var location=new TextBox{Dock=DockStyle.Fill,MaxLength=100};layout.Controls.Add(location);var note=new Label{Text="Saved information applies to every page of new calculation PDFs and print previews in both calculation apps. Save before exporting. Existing PDFs keep their original headers.",Dock=DockStyle.Fill};layout.Controls.Add(note);var save=new Button{Text="Save project information",Dock=DockStyle.Fill,BackColor=Color.White};layout.Controls.Add(save);Controls.Add(layout);var current=ProjectInfoStore.Read();name.Text=current.Name;location.Text=current.Location;save.Click+=(s,e)=>{try{ProjectInfoStore.Save(name.Text,location.Text);note.Text="Saved. New PDFs and print previews will use this project name and location.";}catch(Exception ex){MessageBox.Show(this,ex.Message,"Project Information");}};AcceptButton=save;}
}
}
